local pages = {}
local function createPage(name)
	local p = Instance.new("Frame", Content)
	p.Size = UDim2.new(1, 0, 1, 0)
	p.Visible = false
	p.BackgroundTransparency = 1
	pages[name] = p
	return p
end

local function setTab(btn, name)
	for _, p in pairs(pages) do p.Visible = false end
	for _, t in pairs(TabBar:GetChildren()) do
		if t:IsA("TextButton") then
			t.BackgroundColor3 = Color3.fromRGB(22, 14, 38)
			t.TextColor3 = Color3.fromRGB(100, 70, 160)
			local s = t:FindFirstChildOfClass("UIStroke") if s then s:Destroy() end
			local g = t:FindFirstChildOfClass("UIGradient") if g then g:Destroy() end
		end
	end
	pages[name].Visible = true
	btn.BackgroundColor3 = Color3.fromRGB(80, 20, 160)
	btn.TextColor3 = Color3.fromRGB(230, 180, 255)
	local s = Instance.new("UIStroke", btn)
	s.Color = Color3.fromRGB(160, 80, 255)
	s.Thickness = 1
	s.Transparency = 0.3
	local g = Instance.new("UIGradient", btn)
	g.Color = ColorSequence.new({
		ColorSequenceKeypoint.new(0, Color3.fromRGB(100, 30, 200)),
		ColorSequenceKeypoint.new(1, Color3.fromRGB(60, 10, 130))
	})
	g.Rotation = 90
end

local function createTab(name, index)
	local btn = Instance.new("TextButton", TabBar)
	btn.Size = UDim2.new(0, 76, 1, -8)
	btn.LayoutOrder = index
	btn.Text = name:upper()
	btn.BackgroundColor3 = Color3.fromRGB(22, 14, 38)
	btn.TextColor3 = Color3.fromRGB(100, 70, 160)
	btn.Font = Enum.Font.GothamBold
	btn.TextSize = 10
	btn.BorderSizePixel = 0
	Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 7)
	return btn
end

