local function makeActionBtn(parent, text, yPos, accentColor)
	local container = makeCard(parent, yPos, 44)
	local ab = Instance.new("Frame", container)
	ab.Size = UDim2.new(0, 3, 1, -12)
	ab.Position = UDim2.new(0, 0, 0, 6)
	ab.BackgroundColor3 = accentColor or Color3.fromRGB(140, 60, 255)
	ab.BorderSizePixel = 0
	Instance.new("UICorner", ab).CornerRadius = UDim.new(1, 0)
	local lbl = Instance.new("TextLabel", container)
	lbl.Size = UDim2.new(1, -16, 1, 0)
	lbl.Position = UDim2.new(0, 14, 0, 0)
	lbl.BackgroundTransparency = 1
	lbl.Text = text
	lbl.TextColor3 = Color3.fromRGB(210, 190, 240)
	lbl.Font = Enum.Font.GothamBold
	lbl.TextSize = 12
	lbl.TextXAlignment = Enum.TextXAlignment.Left
	local btn = Instance.new("TextButton", container)
	btn.Size = UDim2.new(1, 0, 1, 0)
	btn.BackgroundTransparency = 1
	btn.Text = ""
	local stroke = container:FindFirstChildOfClass("UIStroke")
	btn.MouseEnter:Connect(function() container.BackgroundColor3 = Color3.fromRGB(26, 14, 44) if stroke then stroke.Transparency = 0.2 end end)
	btn.MouseLeave:Connect(function() container.BackgroundColor3 = Color3.fromRGB(16, 10, 28) if stroke then stroke.Transparency = 0.5 end end)
	btn.MouseButton1Down:Connect(function() container.BackgroundColor3 = Color3.fromRGB(40, 16, 70) end)
	btn.MouseButton1Up:Connect(function() container.BackgroundColor3 = Color3.fromRGB(26, 14, 44) end)
	return btn, lbl
end

