local spinConnection
local dotsThread

local function SetStatus(state)
	if spinConnection then spinConnection:Disconnect() spinConnection = nil end
	if dotsThread then task.cancel(dotsThread) dotsThread = nil end

	local color, text, dotColor

	if state == "verifying" then
		color = Color3.fromRGB(59, 130, 246)
		dotColor = Color3.fromRGB(59, 130, 246)
		text = "Verifying access"
		local dots = {".", "..", "...", ""}
		local i = 1
		dotsThread = task.spawn(function()
			while StatusLabel and StatusLabel.Parent do
				if not StatusLabel.Text:find("Verifying", 1, true) then break end
				StatusLabel.Text = text .. dots[i]
				i = (i % #dots) + 1
				task.wait(0.45)
			end
		end)
	elseif state == "success" then
		color = Color3.fromRGB(16, 185, 129)
		dotColor = Color3.fromRGB(16, 185, 129)
		text = "Access Granted"
	elseif state == "error" then
		color = Color3.fromRGB(239, 68, 68)
		dotColor = Color3.fromRGB(239, 68, 68)
		text = "Invalid Key"
	else
		color = Color3.fromRGB(249, 115, 22)
		dotColor = Color3.fromRGB(249, 115, 22)
		text = "No key detected"
	end

	TweenService:Create(StatusLabel, TweenInfo.new(0.35), {TextColor3 = color}):Play()
	TweenService:Create(statusDot, TweenInfo.new(0.35), {BackgroundColor3 = dotColor}):Play()
	StatusLabel.Text = text
end

