end)

checkKeyBtn.MouseButton1Click:Connect(function()
	local key = KeyTextbox.Text:upper()
	SetStatus("verifying")
	checkKeyLbl.Text = "Checking..."
	checkKeyBtn.Active = false

	local result = Junkie.check_key(key)

	checkKeyBtn.Active = true
	checkKeyLbl.Text = "Check Key"

	if not result then
		SetStatus("error")
		checkKeyLbl.Text = "API Error"
		task.wait(1.5)
		checkKeyLbl.Text = "Check Key"
		return
	end

	if result.valid then
		saveVerifiedKey(key)
		getgenv().SCRIPT_KEY = key
		SetStatus("success")
		checkKeyLbl.Text = "Access Granted!"

		task.wait(1.5)

		TweenService:Create(Main, TweenInfo.new(0.4, Enum.EasingStyle.Quint), {BackgroundTransparency = 1}):Play()
		for _, el in pairs(Main:GetDescendants()) do
			if el:IsA("TextLabel") or el:IsA("TextBox") or el:IsA("TextButton") then
				TweenService:Create(el, TweenInfo.new(0.3), {TextTransparency = 1}):Play()
			end
			if el:IsA("GuiObject") and el.BackgroundTransparency < 1 then
				TweenService:Create(el, TweenInfo.new(0.3), {BackgroundTransparency = 1}):Play()
			end
		end

		task.wait(0.5)
		ScreenGui:Destroy()
	else
		SetStatus("error")
		checkKeyLbl.Text = "Wrong Key!"
		task.wait(1.5)
		checkKeyLbl.Text = "Check Key"
	end
end)

